using System.Collections.Generic;
using System.Globalization;
using System.Numerics;
using System.Text.RegularExpressions;

namespace QuettaQuantum
{
    // Data validation only: no selected state, gate application, Execute(), seed,
    // hardware query, or matrix synthesis is performed by this preflight parser.
    public static class SpinDoctorSyntax
    {
        private sealed class Rule { public string Allowed, Required; public Rule(string a,string r){Allowed=a;Required=r;} }
        private static readonly Dictionary<string,Rule> Rules=BuildRules();
        private static void Add(Dictionary<string,Rule> rules,string ns,string actions,string allowed,string required){foreach(string action in actions.Split(' '))rules.Add(ns+" "+action,new Rule(allowed,required));}
        private static Dictionary<string,Rule> BuildRules()
        {
            Dictionary<string,Rule> r=new Dictionary<string,Rule>(StringComparer.OrdinalIgnoreCase);
            Add(r,"q.math","normalize norm probabilities bloch density","amplitudes","amplitudes");Add(r,"q.math","canonical-phase","amplitudes preserve-original","amplitudes");Add(r,"q.math","from-bloch","theta phi","theta phi");Add(r,"q.math","validate-bloch","x y z","x y z");Add(r,"q.math","validate-density purity","rho","rho");Add(r,"q.math","entropy","rho base","rho");Add(r,"q.math","overlap fidelity","a b convention","a b");Add(r,"q.math","trace-distance","rho sigma","rho sigma");Add(r,"q.math","gate-matrix","gate angles","gate");Add(r,"q.math","compare-gates","p rz up-to-global-phase","p rz");Add(r,"q.math","unitary","matrix tolerance","matrix");Add(r,"q.math","tensor","left right","left right");Add(r,"q.math","commutator","a b","a b");Add(r,"q.math","eigen","operator","operator");Add(r,"q.math","expectation","state operator","state operator");
            Add(r,"q.query","amplitudes probabilities","max start","");Add(r,"q.query","expectation","pauli","pauli");Add(r,"q.query","stabilizers","generators","generators");Add(r,"q.query","fidelity","state convention","state");Add(r,"q.query","concurrence reduced-density purity","qubits","qubits");Add(r,"q.query","negativity","partition convention","partition");Add(r,"q.query","marginal","qubits basis","qubits");Add(r,"q.query","entropy","qubits base","qubits");
            Add(r,"q.resource","memory","n representation dtype units","n representation");Add(r,"q.resource","max-n","memory-mib representation dtype overhead-mib","memory-mib representation");Add(r,"q.resource","factor-memory","block-sizes dtype","block-sizes");Add(r,"q.resource","tranche-plan","addresses width semantics","addresses width");Add(r,"q.resource","sampling","probability shots metric","probability shots");Add(r,"q.resource","shots","epsilon delta bound","epsilon delta");Add(r,"q.resource","grover","database-size marked formula","database-size marked");Add(r,"q.resource","qec","logical-qubits physical-per-logical model","logical-qubits physical-per-logical");Add(r,"q.resource","headroom auto","reserve-mib overhead-mib peak-factor representation n","");
            Add(r,"q.model","spectrum","hamiltonian n","hamiltonian n");Add(r,"q.model","evolve","n initial hamiltonian time hbar","n initial hamiltonian time");Add(r,"q.model","ising","h J energy spins","h J");Add(r,"q.model","qubo-to-ising","Q objective mapping","Q");Add(r,"q.model","mbqc","initial resource entangler measurement branch","initial");Add(r,"q.model","compare","models","models");Add(r,"q.model","compare-codes","families assumptions","families assumptions");Add(r,"q.model","topology","braid anyon-model action","");
            Add(r,"q.lesson","amplitude-vs-probability","example","example");Add(r,"q.lesson","entanglement","compare","compare");Add(r,"q.lesson","complexity","classes distinguish","classes distinguish");Add(r,"q.lesson","parallelism","example","");Add(r,"q.lesson","stabilizer","assumptions","assumptions");Add(r,"q.lesson","magic","caveats","caveats");Add(r,"q.lesson","algorithms","compare scope","compare");Add(r,"q.lesson","pqc","standards mode","standards");
            Add(r,"q.noise","apply","state rho channel p gamma lambda convention","channel");Add(r,"q.noise","circuit","n input gates targets independent channel p gamma lambda convention","n input gates targets channel");Add(r,"q.noise","t1","excited-probability time-us t1-us","excited-probability time-us t1-us");Add(r,"q.noise","t2","coherence time-us t2-us","coherence time-us t2-us");Add(r,"q.noise","readout","probabilities confusion orientation","probabilities confusion");Add(r,"q.noise","zne","scales expectations model","scales expectations");
            foreach(string code in new string[]{"repetition3","phase-repetition3"}){r.Add("q.qec "+code+" encode",new Rule("state","state"));r.Add("q.qec "+code+" simulate",new Rule("state error errors recover","state"));}r.Add("q.qec repetition3 syndrome-table",new Rule("errors stabilizers","errors stabilizers"));
            Add(r,"q.qec","validate","stabilizers","stabilizers");Add(r,"q.qec","parameters","n independent-stabilizers","n independent-stabilizers");Add(r,"q.qec","correction-budget","distance","distance");Add(r,"q.qec","compare","mitigation correction","");
            Add(r,"q.compile","universality","set semantics","set");Add(r,"q.compile","identity","left right n equivalence","left right n");Add(r,"q.compile","simplify","n gates preserve-global-phase","n gates");Add(r,"q.compile","count","n gates counting","n gates");Add(r,"q.compile","depth","n gates connectivity scheduling","n gates");Add(r,"q.compile","classify","n gates input","n gates");Add(r,"q.algorithm","phase-estimation","counting-qubits unitary eigenstate power-map inverse-qft","counting-qubits unitary eigenstate");
            return r;
        }
        public static void ValidateSyntax(string[] words)
        {
            if(words==null ||words.Length<2)throw new ArgumentException("Calculator action is required.");string ns=words[0].ToLowerInvariant(),action=words[1].ToLowerInvariant(),key=ns+" "+action,sub="";string[] parse=words;
            if(ns=="q.qec" &&(action=="repetition3" ||action=="phase-repetition3")){if(words.Length<3)throw new ArgumentException("Repetition code requires an explicit subaction.");sub=words[2].ToLowerInvariant();key+=" "+sub;parse=new string[words.Length-1];parse[0]=words[0];parse[1]=words[1];Array.Copy(words,3,parse,2,words.Length-3);}
            Rule rule;if(!Rules.TryGetValue(key,out rule))throw new ArgumentException("No validated syntax/backend for "+key+".");Dictionary<string,string> parsed=SpinDoctorCalculators.ParseFields(parse);SpinDoctorCalculators.CheckFields(parsed,rule.Allowed);Dictionary<string,string> f=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(KeyValuePair<string,string> field in parsed)foreach(string allowed in rule.Allowed.Split(' '))if(allowed.Equals(field.Key,StringComparison.OrdinalIgnoreCase)){f.Add(allowed,field.Value);break;}foreach(string required in rule.Required.Split(new char[]{' '},StringSplitOptions.RemoveEmptyEntries))if(!f.ContainsKey(required))throw new ArgumentException("Missing field "+required+".");
            Dictionary<string,Complex[]> vectors=new Dictionary<string,Complex[]>();Dictionary<string,Complex[,]> matrices=new Dictionary<string,Complex[,]>();
            foreach(KeyValuePair<string,string> field in f)
            {
                string name=field.Key,value=field.Value;
                bool vector=name=="amplitudes"||name=="state"||name=="initial"||name=="eigenstate"||name=="h"||name=="example"&&ns=="q.lesson"&&action=="amplitude-vs-probability"||name=="probabilities"&&ns=="q.noise"||(name=="a"||name=="b")&&ns=="q.math"&&(action=="overlap"||action=="fidelity");
                bool matrix=name=="rho"||name=="sigma"||name=="matrix"||name=="operator"||name=="J"||name=="Q"||name=="confusion"||ns=="q.math"&&(action=="tensor"||action=="commutator")&&(name=="a"||name=="b"||name=="left"||name=="right");
                if(vector){Complex[] v=SpinDoctorCalculators.ParseComplexVector(value);vectors[name]=v;if(name!="h" &&name!="probabilities" &&!(ns=="q.math"&&(action=="normalize"||action=="norm")))SpinDoctorCalculators.RequirePure(v);if(ns=="q.math"&&action=="normalize"&&SpinDoctorCalculators.NormSquared(v)==0)throw new ArgumentException("Cannot normalize the zero vector.");continue;}
                if(matrix){matrices[name]=ParseMatrixData(value);continue;}
                if(Has("theta phi x y z base p rz tolerance probability shots epsilon delta memory-mib overhead-mib reserve-mib time hbar gamma lambda excited-probability time-us t1-us t2-us",name)){double n=SpinDoctorCalculators.Real(value);if((name=="p"&&!(ns=="q.math"))||Has("gamma lambda probability excited-probability",name)){if(n<0||n>1)throw new ArgumentException(name+" must lie in [0,1].");}if(Has("epsilon delta",name)&&(n<=0||n>=1))throw new ArgumentException(name+" must lie in (0,1).");if(name=="base"&&(n<=0||Math.Abs(n-1)<1e-15))throw new ArgumentException("Entropy base must be positive and different from one.");if(Has("time-us overhead-mib",name)&&n<0)throw new ArgumentException(name+" must be nonnegative.");if(Has("memory-mib hbar t1-us t2-us",name)&&n<=0)throw new ArgumentException(name+" must be positive.");if(name=="reserve-mib"&&n<512)throw new ArgumentException("OS reserve must be at least 512 MiB.");if(name=="tolerance"&&(n<=0||n>1e-3))throw new ArgumentException("Tolerance must lie in (0,1e-3].");if(name=="shots"&&(n<1||n>1e15||n!=Math.Floor(n)))throw new ArgumentException("Sampling shots must be integral in 1..1e15.");continue;}
                if(Has("recover independent preserve-original preserve-global-phase up-to-global-phase",name)){bool valueBool=SpinDoctorCalculators.Boolean(value);if(Has("independent preserve-original preserve-global-phase",name)&&!valueBool)throw new ArgumentException(name+" must be true for this backend.");continue;}
                if(Has("start addresses database-size marked logical-qubits physical-per-logical",name)){BigInteger n;if(value.Length>1024||!BigInteger.TryParse(value,NumberStyles.None,CultureInfo.InvariantCulture,out n)||n<(name=="start"?0:1))throw new ArgumentException("Invalid decimal count "+name+".");continue;}
                if(Has("angles scales expectations",name)){double[] a=SpinDoctorCalculators.Angles(value);if(a.Length>64)throw new ArgumentException("Numeric list exceeds 64 entries.");continue;}
                if(name=="qubits"||name=="partition"||name=="targets"){SpinDoctorCalculators.Qubits(value,29,name=="targets"?29:4);continue;}
                if(name=="pauli"){SpinDoctorCalculators.ParsePauli(value,29);continue;}
                if(name=="generators"||name=="stabilizers"){string[] list=SpinDoctorCalculators.SplitList(value);if(list.Length<1||list.Length>64)throw new ArgumentException("Use 1..64 Pauli strings.");foreach(string p in list)SpinDoctorCalculators.ParsePauli(SpinDoctorCalculators.Unquote(p).TrimStart('+','-').Trim(),29);continue;}
                if(name=="block-sizes"){string[] blocks=SpinDoctorCalculators.SplitList(value);if(blocks.Length<1||blocks.Length>1024)throw new ArgumentException("Factor block list is bounded to 1..1024.");foreach(string b in blocks)SpinDoctorCalculators.Integer(b,1,1024);continue;}
                if(Has("models families assumptions compare classes distinguish caveats standards set errors",name)){SpinDoctorCalculators.SplitList(value);continue;}
                if(name=="coherence"){if(Complex.Abs(SpinDoctorCalculators.ComplexExpression(value))>.5+1e-10)throw new ArgumentException("Qubit coherence magnitude exceeds 1/2.");continue;}
            }
            ValidateShapes(ns,action,sub,f,vectors,matrices);ValidateChoices(ns,action,f);
        }
        private static void ValidateShapes(string ns,string action,string sub,Dictionary<string,string> f,Dictionary<string,Complex[]>v,Dictionary<string,Complex[,]>m)
        {
            if(ns=="q.math")
            {
                if(action=="bloch"&&v["amplitudes"].Length!=2)throw new ArgumentException("Bloch vector requires two amplitudes.");if(action=="density"&&v["amplitudes"].Length>16)throw new ArgumentException("Density output dimension exceeds 16.");if(action=="overlap"||action=="fidelity")if(v["a"].Length!=v["b"].Length)throw new ArgumentException("State vector dimensions differ.");
                if(action=="from-bloch"){double t=SpinDoctorCalculators.Real(f["theta"]);if(t<0||t>Math.PI||Math.Abs(SpinDoctorCalculators.Real(f["phi"]))>1e12)throw new ArgumentException("Invalid Bloch angles.");}
                foreach(string name in new string[]{"rho","sigma","matrix","operator"})if(m.ContainsKey(name))Square(m[name]);
                if(action=="trace-distance")SameShape(m["rho"],m["sigma"]);
                if(action=="expectation"&&m["operator"].GetLength(0)!=v["state"].Length)throw new ArgumentException("Observable/state dimensions differ.");
                if(action=="tensor"&&m["left"].GetLength(0)*m["right"].GetLength(0)>16)throw new ArgumentException("Tensor output dimension exceeds 16.");if(action=="commutator"){Square(m["a"]);SameShape(m["a"],m["b"]);}
                if(action=="gate-matrix"){Dictionary<string,object> gate=GateSpec(f["gate"]);double[]angles=f.ContainsKey("angles")?SpinDoctorCalculators.Angles(f["angles"]):new double[0];if(angles.Length!=(int)gate["angleCount"])throw new ArgumentException("Wrong gate angle count.");}
            }
            if(ns=="q.query"){if(f.ContainsKey("max"))SpinDoctorCalculators.Integer(f["max"],1,4096);if(action=="concurrence"&&SpinDoctorCalculators.SplitList(f["qubits"]).Length!=2)throw new ArgumentException("Concurrence requires both qubits.");}
            if(ns=="q.resource"){if(f.ContainsKey("n"))SpinDoctorCalculators.Integer(f["n"],0,1024);if(f.ContainsKey("width"))SpinDoctorCalculators.Integer(f["width"],1,29);if(f.ContainsKey("peak-factor"))SpinDoctorCalculators.Integer(f["peak-factor"],1,8);}
            if(ns=="q.model"){if(action=="spectrum")SpinDoctorCalculators.Integer(f["n"],1,4);if(action=="evolve"){SpinDoctorCalculators.Integer(f["n"],1,1);Qubit(v["initial"]);}if(action=="mbqc")Qubit(v["initial"]);if(action=="ising"){if(v["h"].Length>12)throw new ArgumentException("Ising input exceeds 12 spins.");Square(m["J"]);if(m["J"].GetLength(0)!=v["h"].Length)throw new ArgumentException("Ising h and J dimensions differ.");}if(action=="qubo-to-ising")Square(m["Q"]);if(f.ContainsKey("hamiltonian"))Hamiltonian(f["hamiltonian"],SpinDoctorCalculators.Integer(f["n"],1,4));}
            if(ns=="q.noise")
            {
                if(action=="apply"||action=="circuit"){string channel=f["channel"].ToLowerInvariant();if(!Has("bit-flip phase-flip depolarizing amplitude-damping dephasing",channel))throw new ArgumentException("Unsupported channel.");string parameter=channel=="amplitude-damping"?"gamma":channel=="dephasing"?"lambda":"p";if(!f.ContainsKey(parameter))throw new ArgumentException("Missing channel field "+parameter+".");foreach(string candidate in new string[]{"p","gamma","lambda"})if(candidate!=parameter&&f.ContainsKey(candidate))throw new ArgumentException("Inapplicable channel parameter "+candidate+".");if(action=="apply"){if(v.ContainsKey("state")==m.ContainsKey("rho"))throw new ArgumentException("Supply exactly one state or rho.");if(v.ContainsKey("state"))Qubit(v["state"]);if(m.ContainsKey("rho")&&(m["rho"].GetLength(0)!=2||m["rho"].GetLength(1)!=2))throw new ArgumentException("Noise apply uses one qubit.");}else{int n=SpinDoctorCalculators.Integer(f["n"],1,4);SpinDoctorCalculators.Integer(f["input"],0,(1<<n)-1);GateScript(f["gates"],n);SpinDoctorCalculators.Qubits(f["targets"],n,n);}}
                if(action=="zne"){double[]scales=SpinDoctorCalculators.Angles(f["scales"]),values=SpinDoctorCalculators.Angles(f["expectations"]);if(scales.Length<2||scales.Length>64||scales.Length!=values.Length)throw new ArgumentException("ZNE requires 2..64 matched lists.");HashSet<double>unique=new HashSet<double>();foreach(double s in scales){if(s<=0)throw new ArgumentException("Noise scales must be positive.");unique.Add(s);}if(unique.Count<2)throw new ArgumentException("Noise scales must differ.");}if(action=="readout"){Square(m["confusion"]);if(m["confusion"].GetLength(0)!=v["probabilities"].Length)throw new ArgumentException("Readout dimensions differ.");}
            }
            if(ns=="q.qec"){if(action=="repetition3"||action=="phase-repetition3"){if(sub!="syndrome-table")Qubit(v["state"]);if(sub=="simulate"&&f.ContainsKey("error")==f.ContainsKey("errors"))throw new ArgumentException("Supply exactly one error or errors.");if(sub=="simulate"||sub=="syndrome-table"){string[]errors=f.ContainsKey("error")?new string[]{f["error"]}:SpinDoctorCalculators.SplitList(f["errors"]);if(errors.Length<1||errors.Length>(sub=="syndrome-table"?8:32))throw new ArgumentException("Specified error list exceeds this bounded code example.");foreach(string error in errors){string e=SpinDoctorCalculators.Unquote(error).ToUpperInvariant();if(e!="I"&&!Regex.IsMatch(e,action=="phase-repetition3"?"^Z[012]$":"^X[012]$"))throw new ArgumentException("Unsupported error class or qubit for the selected repetition code.");}}if(sub=="syndrome-table"){string[]st=SpinDoctorCalculators.SplitList(f["stabilizers"]);if(st.Length!=2||SpinDoctorCalculators.Unquote(st[0])!="Z0 Z1"||SpinDoctorCalculators.Unquote(st[1])!="Z1 Z2")throw new ArgumentException("This syndrome table uses Z0 Z1 and Z1 Z2.");}}if(action=="parameters"){int n=SpinDoctorCalculators.Integer(f["n"],1,1000000);SpinDoctorCalculators.Integer(f["independent-stabilizers"],0,n);}if(action=="correction-budget")SpinDoctorCalculators.Integer(f["distance"],1,1000000);}
            if(ns=="q.compile"){int n=action=="universality"?0:SpinDoctorCalculators.Integer(f["n"],1,action=="identity"?4:29);if(action=="identity"){GateScript(f["left"],n);GateScript(f["right"],n);}else if(f.ContainsKey("gates"))GateScript(f["gates"],n);}
            if(ns=="q.algorithm"){int n=SpinDoctorCalculators.Integer(f["counting-qubits"],1,8);Qubit(v["eigenstate"]);if(Complex.Abs(v["eigenstate"][0])>1e-12&&Complex.Abs(v["eigenstate"][1])>1e-12)throw new ArgumentException("Phase estimation requires a computational P eigenstate.");string[]u=Regex.Split(f["unitary"].Trim(),@"\s+");if(u.Length!=3||!u[0].Equals("p",StringComparison.OrdinalIgnoreCase)||SpinDoctorCalculators.Integer(u[2],n,n)!=n||Math.Abs(SpinDoctorCalculators.Real(u[1]))>1e9)throw new ArgumentException("Phase-estimation unitary must be p ANGLE counting-qubits.");}
        }
        private static void ValidateChoices(string ns,string action,Dictionary<string,string>f)
        {
            if(f.ContainsKey("representation")&&!Has("statevector density-matrix unitary",f["representation"].ToLowerInvariant()))throw new ArgumentException("Unknown representation.");Fixed(f,"dtype","complex128");Fixed(f,"units","binary");if(ns=="q.resource"){Fixed(f,"semantics","independent-groups");Fixed(f,"metric","standard-error");Fixed(f,"bound","hoeffding-two-sided");Fixed(f,"formula","asymptotic");Fixed(f,"model","user-supplied-overhead");}if(f.ContainsKey("basis")&&!Has("x y z",f["basis"].ToLowerInvariant()))throw new ArgumentException("Unknown basis.");
            if(ns=="q.math"||ns=="q.query"){if(action=="fidelity")Fixed(f,"convention","squared");if(action=="negativity")Fixed(f,"convention","trace-norm-minus-one-divided-by-two");}
            if(ns=="q.noise"){Fixed(f,"orientation","rows-observed-columns-true");Fixed(f,"model","linear");if(f.ContainsKey("channel")){string channel=f["channel"].ToLowerInvariant();if(channel=="depolarizing")Fixed(f,"convention","mix-with-I-over-2");else if(channel=="dephasing")Fixed(f,"convention","offdiagonal-times-one-minus-lambda");else if(f.ContainsKey("convention"))throw new ArgumentException("This channel has no convention field.");}}
            if(ns=="q.compile"){Fixed(f,"semantics","approximate");Fixed(f,"counting","logical");Fixed(f,"connectivity","all-to-all");Fixed(f,"scheduling","earliest-dependencies");Fixed(f,"input","computational-basis");if(f.ContainsKey("equivalence")&&!Has("exact global-phase",f["equivalence"]))throw new ArgumentException("Unknown equivalence.");}
            if(ns=="q.algorithm"){Fixed(f,"power-map","qj-controls-U^(2^j)");Fixed(f,"inverse-qft","include-final-swaps");}
            if(ns=="q.model"){Fixed(f,"energy","sum_i h_i s_i + sum_i<j J_ij s_i s_j");Fixed(f,"spins","plus-minus-one");Fixed(f,"objective","x_transpose_Q_x");Fixed(f,"mapping","x=(1-s)/2");Fixed(f,"resource","one plus ancilla");Fixed(f,"entangler","CZ");Fixed(f,"measurement","X on input");Fixed(f,"branch","all");Fixed(f,"braid","example");Fixed(f,"anyon-model","unspecified");Fixed(f,"action","explain");}
            if(ns=="q.qec"){Fixed(f,"mitigation","zne");Fixed(f,"correction","stabilizer-code");}if(ns=="q.lesson"){if(action=="parallelism")Fixed(f,"example","grover");Fixed(f,"scope","toy-calculator");Fixed(f,"mode","verify-current-primary-sources");}
            if(ns=="q.compile"&&action=="universality")ExactList(f,"set",new string[]{"h","t","cx"});
            if(ns=="q.model"){if(action=="compare")ExactList(f,"models",new string[]{"gate-based","closed-system-adiabatic","open-system-annealing"});if(action=="compare-codes"){ExactList(f,"families",new string[]{"surface-code","qldpc"});ExactList(f,"assumptions",new string[]{"connectivity","decoder","noise-model","rate","distance"});}}
            if(ns=="q.lesson"){if(action=="entanglement")ExactList(f,"compare",new string[]{"plus tensor plus","Bell phi plus"});if(action=="complexity"){ExactList(f,"classes",new string[]{"P","BPP","BQP","PSPACE","NP"});ExactList(f,"distinguish",new string[]{"proven","conjectured"});}if(action=="stabilizer")ExactList(f,"assumptions",new string[]{"stabilizer-input","clifford-gates","pauli-measurements"});if(action=="magic")ExactList(f,"caveats",new string[]{"input-dependent-T","qubit-Wigner-convention","nonclifford-not-sufficient-for-advantage"});if(action=="algorithms")ExactList(f,"compare",new string[]{"shor","grover"});if(action=="pqc")ExactList(f,"standards",new string[]{"FIPS203","FIPS204","FIPS205"});}
        }
        private static Complex[,] ParseMatrixData(string text){text=text.Trim();if(text.StartsWith("[",StringComparison.Ordinal))return SpinDoctorCalculators.ParseComplexMatrix(text);if(text.Equals("I2",StringComparison.OrdinalIgnoreCase))return new Complex[2,2];Dictionary<string,object>spec=GateSpec(text);if((int)spec["angleCount"]!=0)throw new ArgumentException("Named matrix requires explicit zero-parameter gate.");int d=1<<(int)spec["targetCount"];return new Complex[d,d];}
        private static Dictionary<string,object>GateSpec(string name){name=Alias(name);foreach(Dictionary<string,object>g in TrancheRegister.SupportedGates)if((string)g["name"]==name)return g;throw new ArgumentException("Unsupported gate "+name+".");}
        private static string Alias(string name){name=name.ToLowerInvariant();return name=="id"||name=="identity"?"i":name=="u3"?"u":name=="cnot"?"cx":name=="toffoli"?"ccx":name=="fredkin"?"cswap":name;}
        private static void GateScript(string script,int n){if(script.Length>12000)throw new ArgumentException("Gate script exceeds 12000 characters.");string[]commands=script.Split(';');if(commands.Length>256)throw new ArgumentException("Gate script exceeds 256 instructions.");foreach(string raw in commands){if(String.IsNullOrWhiteSpace(raw))continue;string[]w=Regex.Split(raw.Trim(),@"\s+");Dictionary<string,object>g=GateSpec(w[0]);int a=(int)g["angleCount"],q=(int)g["targetCount"];bool all=w.Length==a+2&&w[w.Length-1].Equals("all",StringComparison.OrdinalIgnoreCase);if(all&&!(bool)g["local"]||!all&&w.Length!=1+a+q)throw new ArgumentException("Wrong gate operands.");for(int i=0;i<a;i++)if(Math.Abs(SpinDoctorCalculators.Real(w[1+i]))>1e12)throw new ArgumentException("Gate angle exceeds finite bound.");HashSet<int>seen=new HashSet<int>();if(!all)for(int i=0;i<q;i++)if(!seen.Add(SpinDoctorCalculators.Integer(w[1+a+i],0,n-1)))throw new ArgumentException("Repeated gate operand.");}}
        private static void Hamiltonian(string text,int n){if(text.Length>2048)throw new ArgumentException("Hamiltonian text exceeds 2048 characters.");string[]terms=text.IndexOf(';')>=0?text.Split(';'):Regex.Split(text.Trim(),@"\s+(?=[+-])|(?<=[0-9A-Za-z)])(?=[+-](?![0-9]+\s*\*))");if(terms.Length>64)throw new ArgumentException("Hamiltonian exceeds 64 terms.");foreach(string raw in terms){string term=raw.Trim();int star=term.IndexOf('*');if(star<1)throw new ArgumentException("Hamiltonian requires coefficient*Pauli terms.");SpinDoctorCalculators.Real(term.Substring(0,star));SpinDoctorCalculators.ParsePauli(term.Substring(star+1).Trim(),n);}}
        private static bool Has(string list,string key){foreach(string item in list.Split(' '))if(item==key)return true;return false;}
        private static void Fixed(Dictionary<string,string>f,string name,string value){if(f.ContainsKey(name)&&!f[name].Equals(value,StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Unsupported "+name+"; expected "+value+".");}
        private static void Qubit(Complex[]v){if(v.Length!=2)throw new ArgumentException("Exactly two qubit amplitudes are required.");}
        private static void Square(Complex[,]m){if(m.GetLength(0)!=m.GetLength(1))throw new ArgumentException("Matrix must be square.");}
        private static void SameShape(Complex[,]a,Complex[,]b){if(a.GetLength(0)!=b.GetLength(0)||a.GetLength(1)!=b.GetLength(1))throw new ArgumentException("Matrix dimensions differ.");}
        private static void ExactList(Dictionary<string,string>f,string field,string[] expected){if(!f.ContainsKey(field))throw new ArgumentException("Missing field "+field+".");HashSet<string>remaining=new HashSet<string>(expected,StringComparer.OrdinalIgnoreCase);foreach(string value in SpinDoctorCalculators.SplitList(f[field]))if(!remaining.Remove(SpinDoctorCalculators.Unquote(value)))throw new ArgumentException("Unsupported or duplicate "+field+" entry.");if(remaining.Count!=0)throw new ArgumentException("Incomplete documented "+field+" list.");}
    }
}
